template:
/* The stylesheet is the computer. State lives in the inputs; the
   cascade settles what is true; the counter is the arithmetic. */

.board { counter-reset: total 0 kept 0; }

/* every checked box adds one. An unchecked box still generates a box, so it
   is the :checked test that decides, not the presence of the element. */
.board input:checked + label { counter-increment: total; }

/* branching without a script: display:none generates NO box, so this rule
   increments nothing at all when the condition fails. That absence is the
   if-statement. */
.board:has(#gate:checked) .row { counter-increment: kept; }
.board:not(:has(#gate:checked)) .row { display: none; }

/* the negative. Declare it, increment it with nothing, print it — the only
   way to state that something is absent in a form a reader can watch. */
.board .out::after {
  content: counter(kept) " of " counter(total);
}
